    /// <summary>
    /// Retrieve the country from primary address or business address
    /// </summary>
    /// <returns>Country region id</returns>
    public LogisticsAddressCountryRegionId METCountryRegionId()
    {
        LogisticsAddressCountryRegionId countryRegionId = this.postalAddress().CountryRegionId;

        // if no country in primary address, look at business address
        if (!countryRegionId)
        {
            countryRegionId = DirParty::findPostalAddressByRole(this.RecId, LogisticsLocationRoleType::Business).CountryRegionId;
        }

        return countryRegionId;
    }
